Servidor MCP.ejemplo:
from mcp.server.fastmcp import FastMCP
mcp = FastMCP("inventario")
@mcp.tool()
def buscar_stock(sku: str) -> dict:
    """Consulta unidades disponibles por SKU."""
    return {"sku": sku, "unidades": 42}
mcp.run(transport="stdio")

